INSERT OR IGNORE INTO pages(slug,title,description,content) VALUES('home','Explore Denton Dene online','Explore the woodland, ponds and paths of Denton Dene with Friends of Denton Dene.','{"title":"Explore Denton Dene online","description":"Explore the woodland, ponds and paths of Denton Dene with Friends of Denton Dene.","sections":[{"type":"text","title":"","html":"<p>Denton Dene, to the west of Newcastle city centre, has a mixture of habitats including a steep wooded dene, open grassland, and small ponds. A peaceful place for walking and getting away from the bustle of city life; popular with dog walkers and nature enthusiasts. There''s also a large grassy area for summer picnics and games.</p><p>Enjoy exploring the network of paths through the ancient woodland, embrace the outdoors and muddy puddles on a nature ramble. You never know what wildlife you will spot, ponds are home to a population of smooth and palmate newts and there is an abundance of birds and wildlife that can be seen.</p><p>The geography of Denton Dene means the paths can be steep in places with some steps, so not all areas are suitable for wheelchairs or pushchairs, however there is a good tarmac path running through the centre of the Dene that gives good access for all.</p><p>The paths can be muddy, so a good pair of outdoor shoes / boots is recommended.</p><p>If you''re feeling active there is also a Parkrun every Saturday morning!</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"button","title":"","html":"","image":"","alt":"","caption":"","url":"https://www.parkrun.org.uk/dentondene/","label":"Denton Dene parkrun","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}}]}');
INSERT OR IGNORE INTO pages(slug,title,description,content) VALUES('about','About the Friends','Find out about Friends of Denton Dene and become a member of our voluntary community group.','{"title":"About the Friends","description":"Find out about Friends of Denton Dene and become a member of our voluntary community group.","sections":[{"type":"text","title":"","html":"<p>Friends of Denton Dene is an independent, voluntary community group working in association with Newcastle City Council.</p><p>We encourage an inclusive community spirit, conserve and improve wildlife, learn about the local environment and celebrate local heritage. We promote wellbeing, leisure and enjoyment, including organising events in Denton Dene.</p><p>We meet as friends to co-ordinate with fellow park users about the continuous upkeep and improvement of our green and pleasant park. We meet regularly so we can all be informed and involved in what is happening in the Dene and join with others in park activities.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"text","title":"Become a friend","html":"<p>Membership of Friends of Denton Dene (FoDD) is open to all individuals over 14 who have an interest in using, promoting, maintaining or learning about Denton Dene. A member will be included on our mailing list and receive information about activities, meetings and events and can also take an active role in the group, i.e. attend meetings, vote, help to plan and run activities and stand to be elected as an Officer.</p><p>There is no membership fee; individuals do not need to be a Member to take part in an activity.</p><p>Young people aged 14–17 may become members and attend meetings and activities with the consent of their parent or guardian, given on the membership form.</p><p>For more information please email <a href=\"mailto:contact@friendsofdentondene.org\">contact@friendsofdentondene.org</a>.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"button","title":"","html":"","image":"","alt":"","caption":"","url":"https://docs.google.com/forms/d/e/1FAIpQLSdip_hIDluDM5Uv98pVssKl8H0cndxSIN9qwAfql8F88dXPeA/viewform?usp=header","label":"Become a member","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"button","title":"","html":"<p>Our constitution was adopted in April 2023 and updated in April 2026. A copy is also available on request.</p>","image":"","alt":"","caption":"","url":"/assets/constitution-april-2026.pdf","label":"Read our constitution (PDF)","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}}]}');
INSERT OR IGNORE INTO pages(slug,title,description,content) VALUES('events','Events','Community events and activities in Denton Dene, including family activities and regular litter picks.','{"title":"Events","description":"Community events and activities in Denton Dene, including family activities and regular litter picks.","sections":[{"type":"text","title":"","html":"<p>We work with community partners and Friends of Denton Dene to organise a range of activities and events. We look forward to welcoming everyone to Denton Dene — if you have an idea please let us know: <a href=\"mailto:contact@friendsofdentondene.org\">contact@friendsofdentondene.org</a>.</p><p>Here are some of the events and activities we currently have planned.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"event","title":"Halloween family activities","html":"<p><strong>11:00–11:45: Litter picking and nature walk.</strong> Meet at Whickham View Bus Terminus.</p><p><strong>12:00–13:30: Crafts, snacks, stories and silent disco.</strong> At Denton Burn Library. Suitable for children under 11. Costumes encouraged.</p>","image":"","alt":"Halloween family activities poster. Full event details follow below.","caption":"","url":"/assets/Halloween.pdf","label":"Download the poster (PDF)","date":"2026-10-31","start":"11:00","end":"13:30","location":"Whickham View Bus Terminus and Denton Burn Library","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"text","title":"Monthly litter picks","html":"<p>We also run regular monthly litter picks. Check our <a href=\"https://www.facebook.com/dentondene/\">Facebook page</a> for the next confirmed dates, or email <a href=\"mailto:contact@friendsofdentondene.org\">contact@friendsofdentondene.org</a>.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"event","title":"Denton Dene wildlife survey","html":"<p>Friends of Denton Dene and the Natural History Society of Northumbria teamed up for a wildlife survey, recording sightings on iNaturalist and building evidence for pond restoration.</p>","image":"/assets/Wildlife%20survey.jpg","alt":"Poster for the wildlife survey on 17 October 2026","caption":"","url":"/assets/Wildlife%20survey.pdf","label":"Original event poster (PDF)","date":"2026-10-17","start":"13:30","end":"15:30","location":"Path junction by the ponds in Denton Dene South","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}}]}');
INSERT OR IGNORE INTO pages(slug,title,description,content) VALUES('maps','Maps','Find Denton Dene in Newcastle upon Tyne and open directions for your visit.','{"title":"Maps","description":"Find Denton Dene in Newcastle upon Tyne and open directions for your visit.","sections":[{"type":"map","title":"","html":"<p>Find Denton Dene to the west of Newcastle city centre. Please read our <a href=\"/accessibility\">accessibility information</a> when planning your visit.</p>","image":"","alt":"","caption":"","url":"https://www.google.com/maps/dir/?api=1&destination=Denton+Dene+Newcastle+upon+Tyne","label":"Open directions in Google Maps","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"text","title":"Illustrated signage draft","html":"<p>This illustrated signage draft was supplied in March 2024. Some path markings and labels were still being corrected, and references to park management have since changed. It is included as an archive of the group’s artwork, rather than confirmed route or accessibility guidance.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/signage-draft.png","alt":"March 2024 signage draft — route details awaiting confirmation","caption":"March 2024 signage draft — route details awaiting confirmation","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"button","title":"","html":"","image":"","alt":"","caption":"","url":"/assets/FoDD%20590x890%20Poster%20March%202024%20Stage%20Four.pdf","label":"Download the archived signage draft","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"text","title":"Suggested walks","html":"<p><em>Temporary text — further information will be added by the group.</em></p><p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}}]}');
INSERT OR IGNORE INTO pages(slug,title,description,content) VALUES('nature','Nature','Discover wildlife in Denton Dene and help record your sightings with iNaturalist.','{"title":"Nature","description":"Discover wildlife in Denton Dene and help record your sightings with iNaturalist.","sections":[{"type":"text","title":"","html":"<p>There’s lots of wildlife to see in Denton Dene: birds, mammals, invertebrates and amphibians, not to mention trees, wildflowers and fungi. If you’re lucky you might even spot newts!</p><p>The varied habitats attract a wide range of species and we’re only just beginning to record them. We’d love your help please.</p><p>We use iNaturalist to identify and record sightings — and best of all you don’t have to be an expert as the app will help you to identify what you have seen — a great way to learn!</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"button","title":"","html":"","image":"","alt":"","caption":"","url":"https://www.inaturalist.org/projects/denton-dene-newcastle-upon-tyne","label":"See Denton Dene on iNaturalist","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/Collared%20Earth%20Star%20funghi.jpeg","alt":"Collared earthstar fungus","caption":"Collared earthstar fungus","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/White%20lipped%20snail.jpeg","alt":"White-lipped snail","caption":"White-lipped snail","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/English%20Oak.jpeg","alt":"English oak","caption":"English oak","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/Hawthorn%20blossom.jpeg","alt":"Hawthorn blossom","caption":"Hawthorn blossom","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/Bluebells.jpeg","alt":"Bluebells","caption":"Bluebells","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"text","title":"","html":"<p>Using iNaturalist to record your sightings also means that they can become research grade data that feeds into national and international monitoring of biodiversity — citizen science in action to help protect our wildlife. <a href=\"https://www.inaturalist.org/\">Find out how iNaturalist works</a>.</p><p>Please download the app on your smartphone and photograph what you see in Denton Dene on your visit. Sightings uploaded with co-ordinates within our boundary will be added to our project page.</p><p>If you are a keen photographer, or have a particular area of interest or expertise, and would like to help us improve our records, please <a href=\"mailto:contact@friendsofdentondene.org\">get in touch</a>.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}}]}');
INSERT OR IGNORE INTO pages(slug,title,description,content) VALUES('heritage','Heritage','Explore local heritage with Friends of Denton Dene.','{"title":"Heritage","description":"Explore local heritage with Friends of Denton Dene.","sections":[{"type":"text","title":"","html":"<p><em>Temporary text — further information will be added by the group.</em></p><p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/tree-cross-section.jpg","alt":"Oak tree cross-section in Denton Dene, supplied by the Friends","caption":"Oak tree cross-section in Denton Dene, supplied by the Friends","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"button","title":"","html":"","image":"","alt":"","caption":"","url":"https://stjamesheritage.com/","label":"St James’ Heritage and Environment Group","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"text","title":"","html":"<p>Have a photograph, memory or piece of local history to share? <a href=\"mailto:contact@friendsofdentondene.org?subject=Denton%20Dene%20heritage%20contribution\">Email the Friends</a>. Please include where the material came from and permission to use it. The group will review contributions before deciding what to publish. You can send corrections by email too.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}}]}');
INSERT OR IGNORE INTO pages(slug,title,description,content) VALUES('accessibility','Accessibility','Plan your visit with information about paths, steps and terrain in Denton Dene.','{"title":"Accessibility","description":"Plan your visit with information about paths, steps and terrain in Denton Dene.","sections":[{"type":"text","title":"","html":"<p>The geography of Denton Dene means the paths can be steep in places with some steps, so not all areas are suitable for wheelchairs or pushchairs. There is a tarmac path running through the centre of the Dene that offers better access.</p><p>Paths can be muddy, so a good pair of outdoor shoes or boots is recommended.</p><p>If you would like to discuss your visit, please <a href=\"mailto:contact@friendsofdentondene.org\">contact the Friends</a>. See our <a href=\"/maps\">Maps page</a> to find the Dene.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}}]}');
INSERT OR IGNORE INTO pages(slug,title,description,content) VALUES('photos','Photos','Photographs of Denton Dene and its wildlife, shared by the Friends.','{"title":"Photos","description":"Photographs of Denton Dene and its wildlife, shared by the Friends.","sections":[{"type":"text","title":"","html":"<p>A few views and nature sightings from Denton Dene, shared by the Friends. If you have a photograph you would like the group to consider, please <a href=\"mailto:contact@friendsofdentondene.org?subject=Photo%20for%20Denton%20Dene\">email us</a>. Please confirm that you have permission to share it. Contributions are reviewed before publication.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/bg.jpg","alt":"A woodland path through Denton Dene","caption":"A woodland path through Denton Dene","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/Collared%20Earth%20Star%20funghi.jpeg","alt":"Collared earthstar fungus","caption":"Collared earthstar fungus","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/White%20lipped%20snail.jpeg","alt":"White-lipped snail","caption":"White-lipped snail","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/English%20Oak.jpeg","alt":"English oak","caption":"English oak","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/Hawthorn%20blossom.jpeg","alt":"Hawthorn blossom","caption":"Hawthorn blossom","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"image","title":"","html":"","image":"/assets/Bluebells.jpeg","alt":"Bluebells","caption":"Bluebells","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"white","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}}]}');
INSERT OR IGNORE INTO pages(slug,title,description,content) VALUES('contact','Contact','Get in touch with Friends of Denton Dene or find council channels for reporting park problems.','{"title":"Contact","description":"Get in touch with Friends of Denton Dene or find council channels for reporting park problems.","sections":[{"type":"text","title":"","html":"<p>For membership, activities, volunteering and ideas for the group, email <a href=\"mailto:contact@friendsofdentondene.org\">contact@friendsofdentondene.org</a>.</p><p>You can also follow <a href=\"https://www.facebook.com/dentondene/\">Friends of Denton Dene on Facebook</a>.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"text","title":"Report a problem","html":"<p>The Friends is a voluntary community group. Please report maintenance and safety problems to the responsible authority.</p><p>Use <a href=\"https://envirocall.newcastle.gov.uk/\">Newcastle City Council’s Your Local Services</a> for reporting environmental problems. The council’s <a href=\"https://www.newcastle.gov.uk/report\">reporting directory</a> includes fly-tipping, discarded needles, graffiti and vandalism of street furniture.</p><p>To report a fallen or dangerous tree, the council advises calling <a href=\"tel:01912787878\">0191 278 7878</a> and asking for Your Local Services. See the council’s <a href=\"https://new.newcastle.gov.uk/parks-play-spaces-and-allotments\">parks information</a> for current guidance.</p>","image":"","alt":"","caption":"","url":"","label":"","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}},{"type":"button","title":"","html":"","image":"","alt":"","caption":"","url":"https://www.parkrun.org.uk/dentondene/","label":"Denton Dene parkrun","date":"","start":"","end":"","location":"","notes":"","hidden":false,"style":{"align":"left","size":"normal","theme":"light","weight":"normal","space":"normal","width":"normal","radius":"soft","position":"center","fit":"contain","imageSize":"large","button":"solid"}}]}');
